const BRIEF = D + '00-vision\\00-design-brief.md'
const BIBLE = D + '02-architecture\\00-design-bible.md'
const MATRIX = D + '07-tech-landscape\\00-summary-and-selection-matrix.md'
const SCHEMAS = ROOT + '\\schemas\\'

const REVIEW = {
  type: 'object',
  properties: {
    findings: { type: 'array', items: { type: 'object', properties: {
      severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
      location: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' },
    }, required: ['severity', 'location', 'problem', 'fix'] } },
    verdict: { type: 'string', enum: ['accept', 'revise', 'rewrite'] },
  },
  required: ['findings', 'verdict'],
}
const DONE = {
  type: 'object',
  properties: {
    file: { type: 'string' },
    summary: { type: 'string' },
    defined: { type: 'array', items: { type: 'string' }, description: 'types/fields/IDs/endpoints this doc defines that others reference' },
    open_issues: { type: 'array', items: { type: 'string' } },
    extra_files: { type: 'array', items: { type: 'string' }, description: 'other files written (schemas, yaml)' },
  },
  required: ['file', 'summary', 'defined', 'open_issues', 'extra_files'],
}

const conv = (extraReads) => `## 공통 규약 (반드시 준수)
- 순서대로 전부 읽는다: (1) 설계 브리프 ${BRIEF} (2) 설계 바이블 ${BIBLE} (3) 기술 선정 매트릭스 ${MATRIX} ${extraReads ? '(4) ' + extraReads : ''}
- 이 문서의 depends_on에 적은 문서는 실제로 읽고, 그 문서가 정의한 타입·필드·열거값·ID를 **그대로** 사용한다. 설계 바이블의 계약 인벤토리(타입 이름, 핵심 필드)와 결정 레지스터를 절대 임의로 바꾸지 않는다. 필요한 변경은 "## 미해결 이슈"에 제안으로만 남긴다.
- 한국어 본문, 영문 식별자(snake_case 필드, PascalCase 타입). 이모지·ASCII 아트 금지. 다이어그램은 Mermaid.
- frontmatter: title, status: review, owner, version: 0.1.0, last_updated: 2026-09-18, depends_on(실제 읽은 문서 상대경로 배열). 계약 문서는 schema_version 추가.
- 상호참조 링크는 브리프 §8 산출물 맵의 경로만 사용한다.
- 문서 구조: # 제목 → ## 목적 → ## 범위 → 본문 → ## 결정 사항 요약 → ## 미해결 이슈 → ## 참조. 계약 문서는 ## 스키마, ## 예시, ## 불변식(Invariants), ## 버전 이력 절 필수.
- 오픈소스 API·버전·라이선스는 기술 지형 문서(docs/07-tech-landscape)에 근거가 있을 때만 단정한다. 불확실하면 "(확인 필요)".
- 다른 에이전트들이 동시에 다른 문서를 작성 중이다. 지정된 파일(과 명시된 부속 파일)만 쓴다.`

function writeP(d, extraReads) {
  return `당신은 이 오픈소스 RAG 플랫폼의 수석 아키텍트 겸 테크니컬 라이터다. 다음 문서를 작성한다.

파일: ${D}${d.path.replace(/\//g, '\\')}
제목: ${d.title}
depends_on(반드시 읽을 문서): ${JSON.stringify(d.deps || [])}

## 이 문서의 내용 지시
${d.outline}

${conv(extraReads)}

분량 ${d.len || '350~900'}행. Write 도구로 저장 후 구조화 결과를 반환한다(defined에는 이 문서가 정의한 타입/필드/ID/엔드포인트 이름을 나열).`
}
function reviewP(d) {
  return `당신은 까다로운 아키텍처 리뷰어다. 문서를 앵커 문서들과 대조하여 적대적으로 검토한다.

문서: ${D}${d.path.replace(/\//g, '\\')}
앵커: 브리프 ${BRIEF}, 설계 바이블 ${BIBLE}, 선정 매트릭스 ${MATRIX}
이 문서의 depends_on: ${JSON.stringify(d.deps || [])} — 이 문서들도 읽고 대조한다.

검토 항목:
1. 앵커 위반: 바이블의 계약 인벤토리·결정 레지스터·명명 규약과 모순되는 타입/필드/열거값/결정. 브리프 D-xx 위반.
2. 의존 문서와의 불일치: depends_on 문서가 정의한 필드명·타입·ID를 다르게 썼는가(예: chunk_id vs chunkId, 열거값 철자).
3. 임의 결정: 앵커에 없는 결정을 단정적으로 도입했는가(미해결 이슈로 남겨야 함).
4. 완전성: 지시(outline)의 모든 항목이 실질적으로 다뤄졌는가. 계약 문서면 스키마·예시·불변식·버전 이력이 있는가. 예시 JSON이 스키마와 일치하는가(필수 필드 누락, 타입 불일치).
5. 기술 정확성: 오픈소스 API/옵션/라이선스 주장이 docs/07-tech-landscape 문서와 일치하는가. Mermaid 문법 오류. JSON/YAML 문법 오류(코드 블록을 실제로 점검).
6. 우아함: 스테이지 경계·실패 모드·멱등성·관측성이 명확한가. 장식적 산문 대비 실질 내용.
지시(outline): ${d.outline}
문서를 수정하지 말고 결과만 반환한다. 계약·ID·결정 관련은 major/blocker, 문체는 minor.`
}
function fixP(d, review, extraReads) {
  return `당신은 문서의 최종 편집자다. 리뷰 결과를 반영해 문서를 수정한다.

파일: ${D}${d.path.replace(/\//g, '\\')}
리뷰 결과:
${JSON.stringify(review, null, 2).slice(0, 16000)}

blocker/major는 모두 수정하고, minor는 합리적인 것만 반영한다. 리뷰어가 앵커와 다르게 주장하면 앵커(브리프>바이블>ADR)가 우선한다. 수정 후 문서 전체 일관성을 확인하고 frontmatter status를 "active"로 바꾼다. 부속 파일(JSON Schema 등)도 함께 고친다. Edit/Write로 저장 후 구조화 결과를 반환한다.
${conv(extraReads)}`
}

async function produce(docs, extraReads, phaseW, phaseR, phaseF) {
  const out = await pipeline(
    docs,
    (d) => agent(writeP(d, extraReads), { label: `write:${d.path}`, phase: phaseW, schema: DONE }),
    (r, d) => r ? agent(reviewP(d), { label: `review:${d.path}`, phase: phaseR || phaseW, schema: REVIEW }).then((rv) => ({ r, rv })) : null,
    (x, d) => {
      if (!x) return null
      const { r, rv } = x
      const serious = rv ? rv.findings.filter((f) => f.severity !== 'minor').length : 0
      if (rv && rv.verdict === 'accept' && serious === 0) { log(`${d.path}: 리뷰 통과`); return r }
      log(`${d.path}: 리뷰 이슈 ${rv ? rv.findings.length : '?'}개(심각 ${serious}) → 수정`)
      return agent(fixP(d, rv, extraReads), { label: `fix:${d.path}`, phase: phaseF || phaseW, schema: DONE })
    },
  )
  return out
}

