// ---------------------------------------------------------------- run
phase('Wave A: Contracts & Architecture')
log(`Wave A: ${WAVE_A.length}개 문서(계약 15 + 아키텍처 9)`)
const aOut = await produce(WAVE_A, null, 'Wave A: Contracts & Architecture')
const aDone = aOut.filter(Boolean)
log(`Wave A 완료 ${aDone.length}/${WAVE_A.length}`)

// ADRs: derive list from bible
const ADR_LIST = { type: 'object', properties: { adrs: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, slug: { type: 'string' }, title: { type: 'string' }, decision_summary: { type: 'string' }, related: { type: 'array', items: { type: 'string' } } }, required: ['id', 'slug', 'title', 'decision_summary'] } } }, required: ['adrs'] }
const adrList = await agent(`설계 바이블 ${BIBLE} 의 "결정 레지스터"(및 브리프 ${BRIEF} 의 D-01~D-20, O-01~O-10 확정 결과)를 읽고, 작성해야 할 ADR 목록을 반환한다. 규칙: 바이블이 ADR 목록/번호를 이미 제시하면 그것을 그대로 사용한다. 없으면 결정 레지스터의 각 주요 결정(기술 선정·계약 구조·아키텍처 패턴)마다 ADR 1개, 총 24~36개. id는 '0001' 형식 4자리, slug는 영문 kebab-case(예: '0007-hybrid-retrieval-default'), title은 한국어. related에는 D-xx/O-xx ID.`, { label: 'adr:list', phase: 'Wave A: Contracts & Architecture', schema: ADR_LIST })
const ADRS = (adrList && adrList.adrs ? adrList.adrs : []).map((a) => ({
  path: `06-adr/${a.id}-${a.slug.replace(/^\d+-/, '')}.md`, title: `ADR-${a.id}: ${a.title}`, len: '80~220',
  deps: ['02-architecture/00-design-bible.md', '07-tech-landscape/00-summary-and-selection-matrix.md'],
  outline: `MADR 형식으로 작성: frontmatter(title, status: accepted, date: 2026-09-18, deciders: architecture, related: ${JSON.stringify(a.related || [])}) → # ADR-${a.id}: ${a.title} → ## 맥락과 문제 → ## 결정 동인(decision drivers) → ## 고려한 대안(각 대안: 설명, 장점, 단점 — 기술 지형 문서 근거 인용) → ## 결정 → ## 결과(긍정/부정/중립) → ## 준수 확인 방법(어떻게 검증/강제하는가) → ## 재검토 조건 → ## 참조. 결정 요약(바이블): ${a.decision_summary}. 바이블·선정 매트릭스와 정확히 일치해야 하며 새 결정을 만들지 않는다.`,
}))
log(`ADR ${ADRS.length}개 작성`)
const adrOut = ADRS.length ? await produce(ADRS, null, 'Wave A: Contracts & Architecture') : []
const adrIndex = await agent(`${D}06-adr\\ 디렉터리의 모든 ADR 파일을 읽고 인덱스 ${D}06-adr\\README.md 를 작성한다: frontmatter(title: ADR 인덱스, status: active), MADR 소개와 작성 규칙, 상태 정의(proposed/accepted/deprecated/superseded), 표(ID | 제목 | 상태 | 날짜 | 관련 결정(D/O-xx) | 요약 한 줄), 주제별 그룹(파싱/청킹/임베딩/인덱스/검색/오케스트레이션/계약/보안/운영), 새 ADR 절차. 한국어. Write 후 결과 반환.`, { label: 'adr:index', phase: 'Wave A: Contracts & Architecture', schema: DONE })

// Contract consistency pass (barrier justified: needs all contract docs + schemas)
phase('Contract Consistency')
const CONS = { type: 'object', properties: { issues: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'major', 'minor'] } }, required: ['file', 'problem', 'fix', 'severity'] } }, canonical_decisions: { type: 'array', items: { type: 'string' }, description: 'when two docs disagree, the chosen canonical form' } }, required: ['issues', 'canonical_decisions'] }
const cons = await agent(`당신은 계약 일관성 감사자다. ${D}03-contracts\\ 의 15개 문서와 ${SCHEMAS} 의 모든 *.schema.json, 그리고 ${D}02-architecture\\00-design-bible.md 의 계약 인벤토리를 모두 읽는다.
검사: (1) 같은 개념의 필드명·타입·열거값이 문서 간 다르게 쓰인 곳(예: doc_id vs document_id, page vs page_no, score.kind 열거 철자) (2) 참조 무결성(문서 A가 문서 B의 타입을 참조할 때 B에 실제 정의되어 있는가) (3) 공통 봉투·공통 타입($defs) 사용 일관성 (4) JSON 예시가 자기 스키마에 유효한지(필수 필드·타입) — node로 JSON 파싱 검증 (5) 스키마 $id·schema_version·파일명 규약 (6) 바이블 인벤토리와의 일치 (7) ACL/tenant 필드가 모든 인덱스·질의 계약에 있는지(D-09) (8) provenance 체인이 SourceDocument→ParsedDocument→Chunk→IndexRecord→RankedSet→ContextPack까지 끊기지 않는지.
서로 다르면 바이블 > 계약 개요(00) > 상류 계약(생산자) 순으로 정본을 정한다. 수정하지 말고 파일별 이슈 목록과 정본 결정을 반환한다.`, { label: 'contracts:audit', phase: 'Contract Consistency', schema: CONS })
const byFile = {}
for (const i of (cons ? cons.issues : [])) { (byFile[i.file] = byFile[i.file] || []).push(i) }
const consFiles = Object.keys(byFile)
log(`계약 일관성 이슈 ${cons ? cons.issues.length : 0}개, 파일 ${consFiles.length}개`)
await parallel(consFiles.map((f) => () => agent(`계약 일관성 감사 결과를 반영해 파일을 수정한다.
대상 파일(문서 또는 스키마; 경로가 상대면 ${ROOT}\\ 기준): ${f}
정본 결정(반드시 따른다): ${JSON.stringify(cons.canonical_decisions)}
이 파일의 이슈: ${JSON.stringify(byFile[f], null, 1)}
문서와 대응 스키마 파일(schemas/*.schema.json), Pydantic 코드 블록, JSON 예시를 모두 함께 고쳐 일치시킨다. 다른 파일은 수정하지 않는다. 완료 후 무엇을 바꿨는지 요약 반환.`, { label: `contracts:fix:${f.split(/[\\/]/).pop()}`, phase: 'Contract Consistency' })))

// Wave B
phase('Wave B: Pipelines, API, Eval, Ops, Dev, Roadmap')
log(`Wave B: ${WAVE_B.length}개 문서`)
const bOut = await produce(WAVE_B, `${D}03-contracts\\00-contract-overview.md (계약 인벤토리·공통 타입)`, 'Wave B: Pipelines, API, Eval, Ops, Dev, Roadmap')
const bDone = bOut.filter(Boolean)
log(`Wave B 완료 ${bDone.length}/${WAVE_B.length}`)

// OpenAPI assembly (barrier: needs all API docs)
phase('OpenAPI')
const oa = await agent(`당신은 API 스펙 작성자다. ${D}05-api\\01-api-design-guidelines.md, 02-ingestion-api.md, 03-retrieval-api.md, 04-management-api.md, 07-webhooks-and-events.md 와 ${D}03-contracts\\ 의 계약 문서·${SCHEMAS} 스키마를 읽고 ${D}05-api\\openapi.yaml 을 작성한다.
요구: OpenAPI 3.1.0, info(title, version 0.1.0, license Apache-2.0), servers, securitySchemes(bearer JWT, apiKey), tags, 모든 엔드포인트(요청/응답 스키마는 components.schemas에 계약 타입을 정의하되 가능한 한 schemas/ 파일을 $ref 로 참조: '../../schemas/context-pack.schema.json' 형식), 에러 응답(RFC 9457 application/problem+json), 페이지네이션 파라미터 재사용, Idempotency-Key 헤더, 예시(각 주요 엔드포인트 요청·응답 example 1개), operationId 규약(도메인_동작), 폐기 헤더. YAML 문법을 신중히 검증(들여쓰기·따옴표). 가능하면 node로 YAML 파싱 검증을 시도한다(npx yaml 등이 없으면 생략). 작성 후 결과 반환(file=openapi.yaml 경로, defined=operationId 목록).`, { label: 'openapi:assemble', phase: 'OpenAPI', schema: DONE })

return {
  waveA: aDone.map((d) => d.file), waveA_dropped: WAVE_A.filter((d, i) => !aOut[i]).map((d) => d.path),
  adrs: adrOut.filter(Boolean).length, adrIndex: adrIndex ? adrIndex.file : null,
  contractIssues: cons ? cons.issues.length : null,
  waveB: bDone.map((d) => d.file), waveB_dropped: WAVE_B.filter((d, i) => !bOut[i]).map((d) => d.path),
  openapi: oa ? oa.file : null,
  openIssues: [...aDone, ...bDone].flatMap((d) => (d.open_issues || []).map((o) => d.file.split(/[\\/]/).pop() + ': ' + o)),
}
